import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/System-Variables.md","filePath":"manual-en/System-Variables.md","lastUpdated":1785684581000}'),r={name:"manual-en/System-Variables.md"};function n(d,e,i,p,c,l){return t(),s("div",null,[...e[0]||(e[0]=[o('<h4 id="_6-7-2-variables-automatically-defined-by-pspp" tabindex="-1">6.7.2 Variables Automatically Defined by PSPP <a class="header-anchor" href="#_6-7-2-variables-automatically-defined-by-pspp" aria-label="Permalink to &quot;6.7.2 Variables Automatically Defined by PSPP&quot;">​</a></h4><p>There are seven system variables. These are not like ordinary variables because system variables are not always stored. They can be used only in expressions. These system variables, whose values and output formats cannot be modified, are described below.</p><p><code>$CASENUM</code></p><p>Case number of the case at the moment. This changes as cases are shuffled around.</p><p><code>$DATE</code></p><p>Date the PSPP process was started, in format A9, following the pattern <code>DD-MMM-YY</code>.</p><p><code>$DATE11</code></p><p>Date the PSPP process was started, in format A11, following the pattern <code>DD-MMM-YYYY</code>.</p><p><code>$JDATE</code></p><p>Number of days between 15 Oct 1582 and the time the PSPP process was started.</p><p><code>$LENGTH</code></p><p>Page length, in lines, in format F11.</p><p><code>$SYSMIS</code></p><p>System missing value, in format F1.</p><p><code>$TIME</code></p><p>Number of seconds between midnight 14 Oct 1582 and the time the active dataset was read, in format F20.</p><p><code>$WIDTH</code></p><p>Page width, in characters, in format F3.</p>',18)])])}const b=a(r,[["render",n]]);export{h as __pageData,b as default};
